{
  "name": "matteo5-gta6br",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "description": "Matteo 5 — GTA 6 BR: original open-world coastal Brazil game for the browser.",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "three": "0.187.0"
  },
  "devDependencies": {
    "vite": "^7.2.2"
  }
}

import { defineConfig } from 'vite';

export default defineConfig({
  server: { host: '0.0.0.0', port: 3002, strictPort: true },
  preview: { host: '0.0.0.0', port: 3002, strictPort: true },
  build: { target: 'es2020', chunkSizeWarningLimit: 2000 },
});

