/* ============================================================
   MATTEO 5 — GTA 6 BR · original console UI
   ============================================================ */
:root {
  --bg: #05080f;
  --bg-2: #080d18;
  --panel: rgba(13, 20, 36, .72);
  --panel-solid: #0d1424;
  --line: rgba(150, 178, 220, .14);
  --line-strong: rgba(170, 196, 235, .26);
  --txt: #eef4ff;
  --muted: #8c9bb4;
  --muted-2: #66758e;
  --gold: #ffc978;
  --sunset: #ff8a5c;
  --pink: #ff5f8f;
  --teal: #22ddcb;
  --teal-dim: rgba(34, 221, 203, .14);
  --blue: #5aa7ff;
  --red: #ff5964;
  --green: #5ce6a4;
  --radius: 20px;
  --ease: cubic-bezier(.22, .8, .28, 1);
  --font-h: 'Chakra Petch', 'Arial Narrow', sans-serif;
  --font-b: 'Manrope', system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
html { background: var(--bg); }
body {
  margin: 0; color: var(--txt); font-family: var(--font-b);
  background: radial-gradient(1200px 800px at 70% -10%, #1a1b3b 0%, transparent 55%), var(--bg);
  min-height: 100vh; overflow: hidden; -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; border: 0; background: none; }
button:focus-visible, [tabindex]:focus-visible { outline: 2px solid var(--teal); outline-offset: 3px; }
a { color: inherit; text-decoration: none; }
.hidden { display: none !important; }
kbd {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 24px; height: 24px; padding: 0 6px; margin: 0 2px;
  border-radius: 6px; border: 1px solid rgba(195, 214, 240, .24);
  background: linear-gradient(180deg, rgba(255,255,255,.12), rgba(255,255,255,.03));
  box-shadow: 0 1px 0 rgba(0,0,0,.5); font-size: 11px; font-weight: 700; color: #dfe9f8;
  font-family: var(--font-b); white-space: nowrap;
}
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-thumb { background: rgba(150, 178, 220, .25); border-radius: 8px; }
::-webkit-scrollbar-track { background: transparent; }

#app { height: 100vh; overflow: hidden; position: relative; }

/* ---------------- background ---------------- */
.shell {
  position: relative; height: 100%; display: flex; flex-direction: column;
  padding: 0 clamp(18px, 3.2vw, 54px); isolation: isolate;
}
.shell-bg { position: fixed; inset: 0; z-index: -1; overflow: hidden; background: #05080f; }
.aurora {
  position: absolute; border-radius: 50%; filter: blur(100px); opacity: .55;
  animation: auroraFloat 22s ease-in-out infinite alternate;
}
.aurora-a { width: 55vw; height: 55vw; left: -12vw; top: -30vw; background: radial-gradient(circle, rgba(255, 116, 84, .5), transparent 65%); }
.aurora-b { width: 60vw; height: 60vw; right: -20vw; top: -12vw; background: radial-gradient(circle, rgba(62, 95, 255, .42), transparent 65%); animation-delay: -7s; }
.aurora-c { width: 45vw; height: 45vw; left: 28vw; bottom: -30vw; background: radial-gradient(circle, rgba(24, 214, 198, .28), transparent 65%); animation-delay: -13s; }
@keyframes auroraFloat { from { transform: translate3d(-2%, 0, 0) scale(1); } to { transform: translate3d(4%, 3%, 0) scale(1.12); } }
.grid-fade {
  position: absolute; inset: 0;
  background-image: linear-gradient(rgba(150, 180, 230, .05) 1px, transparent 1px), linear-gradient(90deg, rgba(150, 180, 230, .05) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(ellipse at 50% 20%, #000 0%, transparent 72%);
  -webkit-mask-image: radial-gradient(ellipse at 50% 20%, #000 0%, transparent 72%);
}
.grain {
  position: absolute; inset: 0; opacity: .035; pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
}
.particles { position: absolute; inset: 0; overflow: hidden; }
.particles i {
  position: absolute; width: 3px; height: 3px; border-radius: 50%;
  background: rgba(255, 214, 160, .75); box-shadow: 0 0 8px 2px rgba(255, 190, 120, .25);
  animation: floatUp linear infinite;
}
@keyframes floatUp {
  0% { transform: translateY(20vh) scale(.6); opacity: 0; }
  15% { opacity: .9; }
  80% { opacity: .5; }
  100% { transform: translateY(-90vh) translateX(4vw) scale(1.1); opacity: 0; }
}

/* ---------------- top bar ---------------- */
.topbar {
  height: 76px; flex: 0 0 76px; display: flex; align-items: center; gap: 30px;
  border-bottom: 1px solid rgba(160, 190, 230, .09);
}
.brand { display: flex; align-items: center; gap: 10px; }
.brand-mark { width: 34px; height: 34px; display: grid; place-items: center; filter: drop-shadow(0 0 10px rgba(255, 150, 100, .25)); }
.brand-mark svg { width: 100%; height: 100%; }
.brand-word { font-family: var(--font-h); font-weight: 700; letter-spacing: .14em; font-size: 17px; }
.brand-5 { color: var(--sunset); margin-left: 2px; }
.topnav { display: flex; align-items: center; gap: 4px; margin-left: 8px; }
.topnav-item {
  position: relative; padding: 11px 15px; border-radius: 10px; color: #aab7ca;
  font-size: 13.5px; font-weight: 600; letter-spacing: .01em; transition: .18s var(--ease);
}
.topnav-item:hover { color: #fff; background: rgba(255,255,255,.06); }
.topnav-item.active { color: #fff; }
.topnav-item.active::after {
  content: ''; position: absolute; left: 15px; right: 15px; bottom: 2px; height: 2px;
  border-radius: 2px; background: linear-gradient(90deg, var(--sunset), var(--pink));
  box-shadow: 0 0 12px rgba(255, 110, 100, .55);
}
.topstatus { margin-left: auto; display: flex; align-items: center; gap: 14px; color: #aab7ca; font-size: 12.5px; }
.status-chip { display: inline-flex; align-items: center; gap: 6px; padding: 5px 9px; border: 1px solid var(--line); border-radius: 100px; background: rgba(255,255,255,.03); }
.dot-online { width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); display: inline-block; }
.dot-online.big { width: 8px; height: 8px; }
.clock { font-family: var(--font-h); font-size: 15px; letter-spacing: .08em; color: #e8f0fc; }
.sysicons { display: inline-flex; align-items: center; gap: 9px; color: #b9c6d8; }
.ico-wifi { width: 19px; height: 14px; }
.ico-bat { width: 24px; height: 14px; }
.avatar {
  width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center;
  background: linear-gradient(140deg, #ffb06a, #ff5f8f 60%, #7a5cff);
  color: #141021; font-weight: 800; font-size: 11.5px; letter-spacing: .04em;
  border: 1px solid rgba(255,255,255,.35); box-shadow: 0 2px 12px rgba(255, 110, 140, .3);
}

/* ---------------- dashboard ---------------- */
.dash {
  flex: 1 1 auto; min-height: 0; display: grid;
  grid-template-columns: minmax(0, 1fr) 336px;
  grid-template-rows: minmax(0, 1fr) auto;
  gap: clamp(14px, 1.6vw, 22px);
  padding: 20px 0 12px;
}
.hero-card {
  position: relative; border-radius: 26px; overflow: hidden; min-height: 0;
  border: 1px solid rgba(255, 255, 255, .12);
  background: #0b1120;
  box-shadow: 0 36px 90px -30px rgba(0, 0, 0, .9), inset 0 1px 0 rgba(255, 255, 255, .14);
  display: flex; flex-direction: column;
}
.hero-art { position: absolute; inset: 0; overflow: hidden; }
.hero-art svg { width: 100%; height: 100%; object-fit: cover; transform: scale(1.01); }
.hero-art::after {
  content: ''; position: absolute; inset: 0;
  background:
    linear-gradient(90deg, rgba(5, 8, 15, .94) 0%, rgba(5, 8, 15, .72) 33%, rgba(5, 8, 15, .05) 66%, rgba(5, 8, 15, .2) 100%),
    linear-gradient(0deg, rgba(5, 8, 15, .98) 0%, rgba(5, 8, 15, .42) 32%, transparent 62%);
}
.hero-scan {
  position: absolute; inset: 0; pointer-events: none; opacity: .35;
  background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(0,0,0,.14) 3px 4px);
  mix-blend-mode: multiply;
}
.hero-topline { position: relative; z-index: 2; display: flex; align-items: center; gap: 8px; padding: 20px 24px 0; }
.pill {
  display: inline-flex; align-items: center; gap: 7px; height: 27px; padding: 0 11px;
  border-radius: 100px; font-family: var(--font-h); font-size: 10px; font-weight: 700; letter-spacing: .16em;
}
.pill-gold { color: #1a1108; background: linear-gradient(90deg, #ffd58f, #ffb769); box-shadow: 0 4px 18px rgba(255, 170, 90, .25); }
.pill-dot { width: 5px; height: 5px; border-radius: 50%; background: #4b2a0e; }
.pill-ghost { color: #d6e1f0; border: 1px solid rgba(255,255,255,.22); background: rgba(10, 15, 28, .45); backdrop-filter: blur(8px); }
.pill-ghost.installed { color: #90f0cd; border-color: rgba(92, 230, 164, .4); background: rgba(20, 60, 45, .35); }
.hero-content {
  position: relative; z-index: 2; margin-top: auto; padding: 0 30px clamp(18px, 2.2vh, 28px);
  max-width: min(640px, 70%);
}
.game-logo { margin-bottom: 12px; }
.logo-row { display: flex; align-items: flex-start; line-height: .78; }
.logo-gta {
  font-family: var(--font-h); font-weight: 700; font-style: italic; font-size: clamp(34px, 3.6vw, 56px);
  letter-spacing: -.03em; color: #fff; text-shadow: 0 2px 22px rgba(0,0,0,.5); margin-top: .32em;
  transform: skewX(-4deg);
}
.logo-six {
  font-family: var(--font-h); font-weight: 700; font-size: clamp(76px, 8.3vw, 132px);
  letter-spacing: -.06em; line-height: .72; margin-left: 6px;
  background: linear-gradient(175deg, #fff3cf 0%, #ffc37a 32%, #ff7f5c 62%, #ff4f83 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 8px 26px rgba(255, 100, 90, .25));
}
.logo-br {
  align-self: center; margin-left: 12px; margin-top: .35em; padding: 3px 7px;
  font-family: var(--font-h); font-weight: 700; font-size: clamp(16px, 1.7vw, 24px); letter-spacing: .06em;
  color: #06131a; background: linear-gradient(160deg, #73fff0, #1cc8bd);
  border-radius: 5px; box-shadow: 0 5px 18px rgba(28, 220, 200, .22);
}
.logo-rule { display: flex; align-items: center; gap: 9px; margin-top: 10px; color: #f0d9b8; }
.logo-rule span { height: 1px; width: 26px; background: linear-gradient(90deg, transparent, rgba(255, 210, 155, .8)); }
.logo-rule span:last-child { background: linear-gradient(90deg, rgba(255, 210, 155, .8), transparent); }
.logo-rule b { font-family: var(--font-h); font-size: 11.5px; letter-spacing: .42em; font-weight: 600; }
.logo-tag { margin: 8px 0 0; font-family: var(--font-h); font-size: 10.5px; letter-spacing: .24em; color: #ffcfa1; opacity: .85; }
.hero-desc { color: #bcc7d9; font-size: 13.5px; line-height: 1.55; max-width: 490px; margin: 0 0 18px; text-shadow: 0 1px 8px rgba(0,0,0,.5); }
.hero-actions { display: flex; align-items: stretch; gap: 10px; flex-wrap: wrap; }
.btn {
  position: relative; display: inline-flex; align-items: center; gap: 10px; padding: 10px 18px;
  border-radius: 13px; transition: transform .18s var(--ease), box-shadow .18s var(--ease), background .18s var(--ease), border-color .18s;
  border: 1px solid transparent; text-align: left; overflow: hidden;
}
.btn:active { transform: translateY(1px) scale(.995); }
.btn-primary {
  color: #160f08; background: linear-gradient(100deg, #ffe0ae, #ffb169 40%, #ff8c68);
  box-shadow: 0 10px 32px -8px rgba(255, 150, 90, .55), inset 0 1px 0 rgba(255,255,255,.6);
  border-color: rgba(255, 240, 210, .45);
}
.btn-primary::after {
  content: ''; position: absolute; inset: 0; background: linear-gradient(110deg, transparent 20%, rgba(255,255,255,.45) 45%, transparent 60%);
  transform: translateX(-130%); transition: transform .6s; pointer-events: none;
}
.btn-primary:hover { background: linear-gradient(100deg, #fff0d2, #ffc47f 40%, #ff9a74); box-shadow: 0 14px 40px -8px rgba(255, 160, 100, .7), inset 0 1px 0 rgba(255,255,255,.75); }
.btn-primary:hover::after { transform: translateX(130%); }
.btn-primary[disabled] { opacity: .65; cursor: not-allowed; transform: none; }
.btn-label { display: flex; flex-direction: column; gap: 1px; }
.btn-label b { font-family: var(--font-h); font-size: 13.5px; letter-spacing: .08em; font-weight: 700; text-transform: uppercase; white-space: nowrap; }
.btn-label small { font-size: 10.5px; opacity: .62; font-weight: 600; letter-spacing: .01em; white-space: nowrap; }
.btn-ico { width: 30px; height: 30px; display: grid; place-items: center; border-radius: 9px; background: rgba(0,0,0,.14); flex: 0 0 30px; }
.btn-ico svg { width: 17px; height: 17px; }
.btn-ghost {
  color: #e8f0fc; background: rgba(14, 22, 38, .55); border-color: rgba(180, 206, 240, .2);
  backdrop-filter: blur(12px);
}
.btn-ghost:hover { background: rgba(30, 42, 64, .7); border-color: rgba(190, 215, 250, .35); }
.btn-ghost .btn-ico { background: rgba(255,255,255,.08); }
.btn-icon { width: 52px; justify-content: center; padding: 0; color: #e8f0fc; background: rgba(14, 22, 38, .55); border-color: rgba(180, 206, 240, .2); backdrop-filter: blur(12px); }
.btn-icon svg { width: 21px; height: 21px; }
.btn-icon:hover { color: #ff9a9a; border-color: rgba(255, 120, 120, .35); }
.btn-icon.faved { color: #ff7c96; background: rgba(90, 25, 50, .45); }
.btn-icon.faved svg { fill: currentColor; }
.btn-sm { padding: 8px 15px; border-radius: 10px; }
.btn-sm .btn-label b { font-size: 12px; }
.hero-progress { margin-top: 14px; display: none; align-items: center; gap: 10px; max-width: 420px; font-size: 11px; color: #dce7f6; }
.hero-progress.show { display: flex; }
.hero-progress-bar { flex: 1; height: 5px; border-radius: 5px; background: rgba(255,255,255,.13); overflow: hidden; }
.hero-progress-bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--teal), #7ef4dc); box-shadow: 0 0 12px rgba(60, 230, 210, .6); transition: width .2s linear; }
.hero-meta {
  position: relative; z-index: 2; display: flex; align-items: center; gap: 18px; flex-wrap: wrap;
  padding: 12px 26px; margin-top: 0; border-top: 1px solid rgba(255,255,255,.09);
  background: linear-gradient(0deg, rgba(4, 8, 15, .72), rgba(4, 8, 15, .12)); backdrop-filter: blur(10px);
}
.meta-item { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 600; letter-spacing: .03em; color: #aebbd0; }
.meta-item svg { width: 15px; height: 15px; color: var(--teal); opacity: .85; }
.meta-item.rating { margin-left: auto; color: #93a2b8; font-size: 10px; }
.meta-item.rating b { display: inline-grid; place-items: center; width: 22px; height: 22px; border-radius: 5px; border: 1px solid rgba(255,255,255,.3); color: #fff; font-family: var(--font-h); font-size: 12px; }

/* ---------------- system column ---------------- */
.sys-column { min-height: 0; display: flex; flex-direction: column; gap: 14px; overflow: hidden; }
.sys-card {
  flex: 1 1 auto; min-height: 0; border-radius: 22px; padding: 18px;
  border: 1px solid rgba(170, 198, 238, .14);
  background: linear-gradient(160deg, rgba(22, 31, 52, .86), rgba(8, 13, 24, .82));
  backdrop-filter: blur(22px); box-shadow: 0 30px 70px -30px rgba(0,0,0,.8), inset 0 1px 0 rgba(255,255,255,.07);
  display: flex; flex-direction: column; gap: 14px; overflow-y: auto;
}
.sys-card header { display: flex; align-items: center; justify-content: space-between; }
.sys-kicker { font-family: var(--font-h); font-size: 10px; letter-spacing: .28em; color: var(--muted); }
.sys-ver { font-family: var(--font-h); font-size: 10px; color: var(--teal); background: var(--teal-dim); padding: 3px 7px; border-radius: 5px; letter-spacing: .06em; }
.sys-device { display: flex; align-items: center; gap: 12px; padding: 10px; border-radius: 14px; border: 1px solid rgba(160,190,230,.1); background: rgba(0,0,0,.18); }
.device-art { width: 84px; height: 58px; flex: 0 0 84px; }
.device-art svg { width: 100%; height: 100%; }
.sys-device b { display: block; font-family: var(--font-h); font-size: 14px; letter-spacing: .03em; }
.sys-device span { display: block; font-size: 10.5px; color: var(--muted); margin-top: 2px; }
.sys-device .dot-online { margin-left: auto; }
.storage-row { display: flex; justify-content: space-between; font-size: 10.5px; color: var(--muted); margin-bottom: 6px; }
.storage-row span:last-child { color: #c3cfe0; font-weight: 600; }
.storage-bar { display: flex; height: 6px; border-radius: 6px; overflow: hidden; background: rgba(255,255,255,.08); }
.storage-bar i { background: linear-gradient(90deg, #5b6b87, #7c8ba4); height: 100%; }
.storage-bar b { background: linear-gradient(90deg, var(--sunset), var(--pink)); height: 100%; }
.storage-key { display: flex; gap: 14px; margin-top: 7px; font-size: 9.5px; color: var(--muted-2); }
.storage-key span { display: inline-flex; align-items: center; gap: 5px; }
.storage-key i { width: 5px; height: 5px; border-radius: 50%; display: inline-block; }
.key-a { background: #7c8ba4; } .key-b { background: var(--sunset); }
.sys-rows { display: flex; flex-direction: column; gap: 2px; }
.sys-row { display: flex; align-items: center; gap: 10px; padding: 9px 8px; border-radius: 10px; }
.sys-row:hover { background: rgba(255,255,255,.03); }
.sys-ico { width: 28px; height: 28px; display: grid; place-items: center; border-radius: 8px; background: rgba(255,255,255,.05); font-size: 12px; flex: 0 0 28px; }
.sys-row div { display: flex; flex-direction: column; }
.sys-row b { font-size: 11.5px; font-weight: 600; }
.sys-row small { font-size: 9.5px; color: var(--muted-2); margin-top: 1px; }
.tag-on, .tag-live { margin-left: auto; font-family: var(--font-h); font-size: 8px; letter-spacing: .1em; padding: 3px 6px; border-radius: 4px; font-weight: 700; }
.tag-on { color: var(--teal); background: rgba(34,221,203,.1); }
.tag-live { color: #ffc978; background: rgba(255,201,120,.1); }
.sys-action {
  margin-top: auto; width: 100%; display: flex; align-items: center; justify-content: space-between;
  padding: 10px 12px; border-radius: 11px; border: 1px solid rgba(170,198,238,.15);
  background: rgba(255,255,255,.03); color: #c7d4e6; font-size: 10.5px; transition: .18s;
}
.sys-action:hover { border-color: rgba(34,221,203,.3); color: #fff; background: rgba(34,221,203,.06); }
.sys-action span { font-size: 18px; color: var(--teal); line-height: 1; }
.tip-card {
  flex: 0 0 auto; border-radius: 18px; padding: 14px 16px;
  border: 1px solid rgba(255, 191, 120, .16);
  background: linear-gradient(140deg, rgba(58, 39, 27, .45), rgba(12, 17, 29, .7));
  backdrop-filter: blur(14px);
}
.tip-kicker { font-family: var(--font-h); font-size: 8.5px; letter-spacing: .24em; color: var(--gold); }
.tip-card p { margin: 6px 0 8px; font-size: 10.5px; line-height: 1.5; color: #c8d1df; }
.tip-dots { display: flex; gap: 4px; }
.tip-dots i { width: 4px; height: 4px; border-radius: 50%; background: rgba(255,255,255,.18); }
.tip-dots i.on { width: 12px; border-radius: 4px; background: var(--gold); }

/* ---------------- tiles ---------------- */
.tile-row {
  grid-column: 1 / -1; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px;
}
.tile {
  display: flex; align-items: center; gap: 11px; padding: 11px 13px; border-radius: 15px;
  border: 1px solid rgba(170, 198, 238, .12); background: rgba(15, 22, 38, .55);
  backdrop-filter: blur(16px); text-align: left; transition: .2s var(--ease); min-width: 0;
}
.tile:hover { transform: translateY(-2px); border-color: rgba(190, 215, 250, .3); background: rgba(27, 37, 58, .7); box-shadow: 0 12px 30px -16px rgba(0,0,0,.9); }
.tile-ico { width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center; flex: 0 0 36px; border: 1px solid rgba(255,255,255,.1); }
.tile-ico svg { width: 20px; height: 20px; }
.tile-story { color: #ffc978; background: linear-gradient(150deg, rgba(255,170,90,.2), rgba(255,100,100,.06)); }
.tile-rp { color: var(--teal); background: linear-gradient(150deg, rgba(34,221,203,.18), rgba(34,221,203,.03)); }
.tile-gal { color: #b4a2ff; background: linear-gradient(150deg, rgba(150,120,255,.18), rgba(150,120,255,.03)); }
.tile-set { color: #9dc2ff; background: linear-gradient(150deg, rgba(100,160,255,.16), rgba(100,160,255,.03)); }
.tile-cred { color: #ff9db6; background: linear-gradient(150deg, rgba(255,120,160,.16), rgba(255,120,160,.03)); }
.tile-body { display: flex; flex-direction: column; min-width: 0; }
.tile-body b { font-size: 11.5px; font-weight: 700; letter-spacing: .01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tile-body small { font-size: 9px; color: var(--muted-2); margin-top: 1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.tile-go { margin-left: auto; color: var(--muted-2); font-size: 18px; transition: .2s; }
.tile:hover .tile-go { color: #fff; transform: translateX(2px); }

.shell-foot {
  flex: 0 0 34px; display: flex; align-items: center; gap: 10px;
  border-top: 1px solid rgba(160,190,230,.08); font-size: 9.5px; color: var(--muted-2);
}
.foot-sep { opacity: .5; }
.foot-right { margin-left: auto; }
.foot-right b { color: var(--teal); font-weight: 600; }

/* ---------------- boot ---------------- */
.boot-overlay {
  position: fixed; inset: 0; z-index: 200; display: flex; flex-direction: column; align-items: center; justify-content: center;
  background: radial-gradient(700px 500px at 50% 45%, #0d1424 0%, #04070d 70%); transition: opacity .7s var(--ease), visibility .7s;
}
.boot-overlay.done { opacity: 0; visibility: hidden; }
.boot-mark { width: 68px; height: 68px; animation: bootPulse 2.4s ease-in-out infinite; }
.boot-mark svg { width: 100%; height: 100%; }
@keyframes bootPulse { 0%,100% { opacity: .75; filter: drop-shadow(0 0 0 rgba(255,150,100,0)); } 50% { opacity: 1; filter: drop-shadow(0 0 18px rgba(255,150,100,.35)); } }
.boot-name { font-family: var(--font-h); font-size: 26px; letter-spacing: .3em; font-weight: 700; margin-top: 12px; }
.boot-name span { color: var(--sunset); margin-left: 4px; }
.boot-bar { width: 190px; height: 2px; background: rgba(255,255,255,.1); margin-top: 22px; overflow: hidden; border-radius: 2px; }
.boot-bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--sunset), var(--pink)); animation: bootBar 1.15s var(--ease) forwards; }
@keyframes bootBar { to { width: 100%; } }
.boot-status { margin-top: 12px; font-size: 9.5px; letter-spacing: .22em; text-transform: uppercase; color: var(--muted-2); }

/* ---------------- modals ---------------- */
.modal-layer {
  position: fixed; inset: 0; z-index: 120; display: flex; align-items: center; justify-content: center;
  padding: 26px; background: rgba(3, 6, 12, .7); backdrop-filter: blur(18px);
  animation: fadeIn .3s var(--ease);
}
@keyframes fadeIn { from { opacity: 0; } }
.modal-layer.closing { animation: fadeOut .25s var(--ease) forwards; }
@keyframes fadeOut { to { opacity: 0; } }
.modal {
  position: relative; width: min(820px, 100%); max-height: calc(100vh - 52px); overflow: auto;
  border-radius: 24px; border: 1px solid rgba(180, 205, 240, .18);
  background: linear-gradient(165deg, rgba(22, 31, 52, .98), rgba(8, 12, 22, .99));
  box-shadow: 0 50px 120px -30px rgba(0,0,0,.95), inset 0 1px 0 rgba(255,255,255,.08);
  padding: 24px; animation: modalIn .4s var(--ease);
}
@keyframes modalIn { from { transform: translateY(16px) scale(.985); opacity: 0; } }
.modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; margin-bottom: 18px; }
.eyebrow { display: block; font-family: var(--font-h); font-size: 9px; letter-spacing: .26em; color: var(--sunset); margin-bottom: 6px; }
.modal h2 { margin: 0; font-family: var(--font-h); font-size: 24px; letter-spacing: .015em; font-weight: 600; }
.modal h3 { font-family: var(--font-h); font-size: 12px; letter-spacing: .12em; text-transform: uppercase; color: #cfdaea; margin: 0 0 8px; font-weight: 600; }
.modal-x {
  width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center; color: #aab7ca;
  border: 1px solid var(--line); background: rgba(255,255,255,.03); font-size: 13px; transition: .18s; flex: 0 0 34px;
}
.modal-x:hover { background: rgba(255,255,255,.09); color: #fff; }
.modal-foot { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-top: 18px; padding-top: 16px; border-top: 1px solid var(--line); font-size: 10.5px; color: var(--muted); }
.fineprint { font-size: 9.5px; line-height: 1.55; color: var(--muted-2); margin: 14px 0 0; }

/* install */
.install-modal { width: min(760px, 100%); }
.install-hero { display: flex; gap: 18px; align-items: stretch; }
.install-thumb {
  position: relative; width: 250px; flex: 0 0 250px; min-height: 138px; border-radius: 15px; overflow: hidden;
  background: linear-gradient(180deg, #2b2450, #e2686b 55%, #ffb066 72%, #12405a 73%, #071e2f);
  border: 1px solid rgba(255,255,255,.16);
}
.install-thumb .mini-sun { position: absolute; width: 48px; height: 48px; border-radius: 50%; right: 38px; top: 44px; background: #ffe0a0; box-shadow: 0 0 50px 18px rgba(255,170,100,.5); }
.mini-skyline { position: absolute; inset: auto 0 38% 0; height: 44px; background: linear-gradient(0deg, #0b1424, #101a2e); clip-path: polygon(0 100%,0 62%,7% 62%,7% 36%,13% 36%,13% 70%,19% 70%,19% 24%,26% 24%,26% 58%,33% 58%,33% 44%,40% 44%,40% 80%,47% 80%,47% 30%,55% 30%,55% 66%,61% 66%,61% 16%,68% 16%,68% 54%,75% 54%,75% 40%,82% 40%,82% 74%,89% 74%,89% 48%,96% 48%,96% 78%,100% 78%,100% 100%); }
.mini-water { position: absolute; inset: auto 0 0 0; height: 30%; background: repeating-linear-gradient(0deg, rgba(255,220,180,.16) 0 1px, transparent 1px 9px), linear-gradient(0deg, #071a28, #1f4a64); }
.install-thumb > span { position: absolute; left: 14px; bottom: 12px; font-family: var(--font-h); font-weight: 700; font-size: 28px; letter-spacing: -.03em; text-shadow: 0 2px 22px rgba(0,0,0,.6); }
.install-thumb > span span { font-size: 40px; background: linear-gradient(180deg, #fff2d3, #ffb36c); -webkit-background-clip: text; background-clip: text; color: transparent; margin: 0 2px; }
.install-thumb > span::after { content: 'BR'; font-size: 11px; color: #05131c; background: var(--teal); padding: 2px 4px; border-radius: 3px; vertical-align: middle; margin-left: 4px; }
.install-info { flex: 1; display: flex; flex-direction: column; justify-content: center; }
.install-size-row { display: flex; align-items: baseline; gap: 10px; }
.install-size-row b { font-family: var(--font-h); font-size: 20px; }
.install-size-row span { font-size: 10px; color: var(--muted); }
.install-info p { font-size: 11.5px; line-height: 1.55; color: #aab7ca; margin: 7px 0 11px; }
.install-tags { display: flex; gap: 5px; flex-wrap: wrap; }
.install-tags span { font-size: 9px; padding: 3px 7px; border-radius: 4px; border: 1px solid var(--line); color: var(--muted); background: rgba(255,255,255,.02); }
.install-progress-wrap { margin: 22px 0 18px; padding: 15px; border-radius: 14px; background: rgba(0,0,0,.24); border: 1px solid var(--line); }
.install-status-row { display: flex; justify-content: space-between; font-size: 11px; margin-bottom: 8px; }
.install-status-row span:first-child { color: #d7e2f2; font-weight: 600; }
.install-status-row span:last-child { font-family: var(--font-h); color: var(--teal); font-size: 13px; }
.install-bar { height: 8px; border-radius: 8px; background: rgba(255,255,255,.08); overflow: hidden; }
.install-bar i { display: block; height: 100%; width: 0; border-radius: 8px; background: linear-gradient(90deg, #1cc8bd, #55f0c4 55%, #ffe0a8); box-shadow: 0 0 18px rgba(50,230,200,.35); transition: width .25s linear; }
.install-sub { display: flex; justify-content: space-between; margin-top: 7px; font-size: 9.5px; color: var(--muted-2); }
.install-actions { display: flex; align-items: center; justify-content: flex-end; gap: 10px; }
.install-actions .btn-primary { min-width: 215px; justify-content: center; }
.install-actions .btn-primary .btn-label { align-items: flex-start; }

/* settings */
.settings-modal { width: min(920px, 100%); height: min(660px, calc(100vh - 52px)); display: flex; flex-direction: column; overflow: hidden; }
.settings-layout { display: flex; gap: 20px; flex: 1; min-height: 0; }
.settings-nav { width: 200px; flex: 0 0 200px; display: flex; flex-direction: column; gap: 3px; border-right: 1px solid var(--line); padding-right: 12px; }
.settings-nav button { text-align: left; padding: 10px 11px; border-radius: 9px; font-size: 11.5px; color: #9fadc2; font-weight: 600; transition: .15s; }
.settings-nav button:hover { background: rgba(255,255,255,.05); color: #e6eefb; }
.settings-nav button.active { color: #fff; background: linear-gradient(90deg, rgba(34,221,203,.14), rgba(34,221,203,.03)); box-shadow: inset 2px 0 0 var(--teal); }
.settings-body { flex: 1; overflow-y: auto; padding: 2px 8px 8px 2px; min-height: 0; }
.settings-page { animation: fadeIn .22s var(--ease); }
.settings-group { margin-bottom: 20px; }
.settings-group > h3 { font-size: 10px; letter-spacing: .18em; color: var(--gold); opacity: .85; border-bottom: 1px solid var(--line); padding-bottom: 7px; margin-bottom: 4px; }
.setting-row { display: flex; align-items: center; gap: 16px; padding: 10px 2px; border-bottom: 1px solid rgba(150,180,220,.07); }
.setting-row:last-child { border-bottom: 0; }
.setting-row.disabled { opacity: .4; pointer-events: none; }
.setting-label { flex: 1; min-width: 0; }
.setting-label b { display: block; font-size: 11.5px; font-weight: 600; }
.setting-label small { display: block; font-size: 9.5px; color: var(--muted-2); margin-top: 2px; line-height: 1.4; }
.setting-control { flex: 0 0 auto; min-width: 176px; display: flex; align-items: center; justify-content: flex-end; gap: 8px; }
.segmented { display: flex; padding: 3px; border-radius: 9px; background: rgba(0,0,0,.26); border: 1px solid var(--line); gap: 2px; }
.segmented button { padding: 5px 9px; border-radius: 6px; font-size: 9.5px; font-weight: 700; color: var(--muted); letter-spacing: .02em; transition: .14s; white-space: nowrap; }
.segmented button:hover { color: #fff; }
.segmented button.active { color: #062019; background: linear-gradient(160deg, #6cf5e4, #22c8ba); box-shadow: 0 2px 10px rgba(34,221,203,.25); }
.segmented.warm button.active { color: #201305; background: linear-gradient(160deg, #ffe0ab, #ffb96e); }
.range-wrap { display: flex; align-items: center; gap: 9px; width: 176px; }
.range-wrap output { font-family: var(--font-h); font-size: 10px; color: var(--teal); min-width: 34px; text-align: right; }
input[type='range'] { -webkit-appearance: none; appearance: none; height: 4px; border-radius: 4px; background: linear-gradient(90deg, var(--teal) var(--fill, 50%), rgba(255,255,255,.13) var(--fill, 50%)); outline: none; flex: 1; cursor: pointer; }
input[type='range']::-webkit-slider-thumb { -webkit-appearance: none; width: 13px; height: 13px; border-radius: 50%; background: #eafffb; border: 3px solid var(--teal); box-shadow: 0 0 10px rgba(34,221,203,.4); }
input[type='range']::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: #eafffb; border: 3px solid var(--teal); }
.toggle { position: relative; width: 38px; height: 21px; border-radius: 20px; background: rgba(255,255,255,.12); border: 1px solid var(--line); transition: .2s; flex: 0 0 38px; }
.toggle::after { content: ''; position: absolute; width: 15px; height: 15px; border-radius: 50%; background: #c2ccdb; top: 2px; left: 2px; transition: .2s var(--ease); }
.toggle.on { background: rgba(34,221,203,.25); border-color: rgba(34,221,203,.5); }
.toggle.on::after { transform: translateX(17px); background: var(--teal); box-shadow: 0 0 10px rgba(34,221,203,.5); }
.setting-select { background: rgba(0,0,0,.28); border: 1px solid var(--line); border-radius: 8px; padding: 6px 9px; font-size: 10.5px; color: #dce6f5; min-width: 150px; }
.setting-select:focus { border-color: var(--teal); outline: none; }
.danger-btn { border: 1px solid rgba(255,110,110,.35); color: #ff9a9a; padding: 7px 12px; border-radius: 8px; font-size: 10px; font-weight: 700; background: rgba(255,80,80,.07); transition: .15s; }
.danger-btn:hover { background: rgba(255,80,80,.15); }
.settings-foot { display: flex; align-items: center; justify-content: space-between; gap: 14px; border-top: 1px solid var(--line); padding-top: 14px; margin-top: 4px; }
.settings-fps { display: flex; align-items: center; gap: 7px; font-size: 9.5px; color: var(--muted-2); }
.fps-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); }
.settings-actions { display: flex; gap: 8px; }

/* how */
.how-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.how-card { border: 1px solid var(--line); border-radius: 13px; padding: 13px; background: rgba(255,255,255,.02); }
.how-card h3 { color: var(--teal); font-size: 9.5px; }
.keyrow { display: flex; align-items: center; gap: 3px; margin: 7px 0; font-size: 9.5px; color: var(--muted); flex-wrap: wrap; }
.keyrow span { margin-right: 6px; }
.keyrow kbd { height: 20px; min-width: 20px; font-size: 9px; padding: 0 5px; }
.how-card p { font-size: 10.5px; line-height: 1.65; color: #a9b7ca; margin: 6px 0 0; }
.how-card p b { color: #e8eefb; }
.ps { font-family: var(--font-b); font-weight: 800; margin: 0 1px; }
.tri { color: #60e6b0; } .cir { color: #ff6f80; } .cro { color: #6cb6ff; } .squ { color: #ff9bd0; }
.how-flow ol { margin: 0; padding-left: 15px; font-size: 10.5px; color: #a9b7ca; line-height: 1.8; }
.how-flow li::marker { color: var(--gold); }

/* gallery */
.gallery-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
.art-card { margin: 0; border-radius: 15px; overflow: hidden; border: 1px solid var(--line); background: rgba(0,0,0,.2); }
.art-scene { position: relative; height: 168px; overflow: hidden; }
.art-1 .art-scene { background: linear-gradient(180deg, #1b1c42 0%, #74416e 45%, #ef7d6f 67%, #ffb775 76%, #134158 77%, #0a2133 100%); }
.art-1 .a-sun { position: absolute; width: 54px; height: 54px; border-radius: 50%; background: #ffe2a5; right: 34px; top: 64px; box-shadow: 0 0 60px 22px rgba(255,170,110,.55); }
.art-1 .a-skyline { position: absolute; inset: auto 0 24% 0; height: 36px; background: #0a1122; clip-path: polygon(0 100%,0 44%,8% 44%,8% 20%,14% 20%,14% 64%,22% 64%,22% 36%,30% 36%,30% 72%,38% 72%,38% 10%,46% 10%,46% 56%,54% 56%,54% 40%,62% 40%,62% 80%,72% 80%,72% 24%,80% 24%,80% 60%,88% 60%,88% 34%,94% 34%,94% 72%,100% 72%,100% 100%); }
.art-1 .a-water { position: absolute; inset: auto 0 0 0; height: 24%; background: repeating-linear-gradient(0deg, rgba(255,220,180,.2) 0 1px, transparent 1px 8px), linear-gradient(0deg, #081b2a, #1e4d67); }
.a-palm { position: absolute; bottom: 0; width: 4px; height: 86px; background: #05101a; border-radius: 4px; transform-origin: bottom; }
.a-palm::before { content: ''; position: absolute; left: -22px; top: -6px; width: 48px; height: 26px; background: #05101a; border-radius: 50% 50% 0 0; clip-path: polygon(50% 100%, 0 40%, 24% 56%, 8% 0, 38% 44%, 50% 0, 62% 44%, 92% 0, 76% 56%, 100% 40%); }
.a-palm.p1 { left: 22px; height: 104px; transform: rotate(4deg); }
.a-palm.p2 { left: 48px; height: 72px; transform: rotate(-6deg); opacity: .8; }
.art-2 .art-scene { background: linear-gradient(180deg, #0a1530, #2b2a55 55%, #71524e 100%); }
.art-2 .a-moon { position: absolute; width: 38px; height: 38px; border-radius: 50%; background: #f4e5c5; left: 38px; top: 28px; box-shadow: 0 0 40px 10px rgba(255,235,190,.22); }
.art-2 .a-hill { position: absolute; inset: auto -20% 16% -10%; height: 90px; background: #111a2b; border-radius: 60% 40% 0 0; transform: rotate(-4deg); }
.art-2 .a-houses { position: absolute; inset: auto 12% 16% 18%; height: 70px; background: repeating-linear-gradient(90deg, #b5535c 0 22px, #d49654 22px 40px, #4f877c 40px 62px, #8f5478 62px 82px); clip-path: polygon(0 100%,0 42%,9% 42%,9% 20%,18% 20%,18% 56%,28% 56%,28% 32%,37% 32%,37% 74%,47% 74%,47% 24%,58% 24%,58% 48%,68% 48%,68% 34%,78% 34%,78% 62%,88% 62%,88% 18%,97% 18%,97% 100%); opacity: .85; }
.art-2 .a-wire { position: absolute; inset: 38% 0 auto 0; height: 20px; border-top: 1px solid rgba(255,240,210,.5); border-radius: 50%; transform: rotate(-5deg); }
.art-3 .art-scene { background: linear-gradient(180deg, #07101f, #102438 62%, #0b1723); }
.art-3 .a-neon { position: absolute; left: 12%; top: 22%; width: 56%; height: 42%; border: 2px solid rgba(255,90,130,.8); border-radius: 4px; box-shadow: inset 0 0 24px rgba(255,90,130,.25), 0 0 24px rgba(255,90,130,.3); transform: perspective(200px) rotateY(-12deg); }
.art-3 .a-road { position: absolute; inset: 58% 0 0 0; background: linear-gradient(180deg, #152738, #060c14); }
